```python
from typing import TypeVar, Generic, Optional

T = TypeVar('T')

class Node(Generic[T]):
    """Linked list node."""

    def __init__(self, value: T):
        self.value = value
        self.next = None


class LinkedList(Generic[T]):
    """Linked list data structure."""

    def __init__(self):
        self.head = None

    def append(self, value: T) -> None:
        """Add a new node to the end of the linked list."""

        if not self.head:
            self.head = Node(value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(value)

    def remove(self, value: T) -> bool:
        """Remove the first occurrence of a node with the given value."""

        if not self.head:
            return False

        if self.head.value == value:
            self.head = self.head.next
            return True

        current = self.head
        while current.next:
            if current.next.value == value:
                current.next = current.next.next
                return True
            current = current.next

        return False

    def search(self, value: T) -> Optional[T]:
        """Find the first occurrence of a node with the given value."""

        current = self.head
        while current:
            if current.value == value:
                return current.value
            current = current.next

        return None

    def __str__(self) -> str:
        """Return a string representation of the linked list."""

        values = []
        current = self.head
        while current:
            values.append(str(current.value))
            current = current.next
        return ' -> '.join(values)


# Example usage:

linked_list = LinkedList[int]

linked_list.append(1)
linked_list.append(2)
linked_list.append(3)

print(linked_list)  # Output: 1 -> 2 -> 3

print(linked_list.search(2))  # Output: 2
print(linked_list.remove(2))   # Output: True
print(linked_list)           # Output: 1 -> 3

linked_list.append(4)
print(linked_list)          # Output: 1 -> 3 -> 4
